class Solution {
public:
    int findLUSlength(vector<string>& strs) {
        auto isSubseq = [](const string& s1, const string& s2) {
            int i = 0;
            for (char ch : s2) {
                if (i < (int)s1.size() && s1[i] == ch) i++;
            }
            return i == (int)s1.size();
        };
        sort(strs.begin(), strs.end(), [](const string& a, const string& b) {
            return a.size() > b.size();
        });
        int n = strs.size();
        for (int i = 0; i < n; i++) {
            bool ok = true;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                if (isSubseq(strs[i], strs[j])) {
                    ok = false;
                    break;
                }
            }
            if (ok) return strs[i].size();
        }
        return -1;
    }
};

class Solution {
    public int findLUSlength(String[] strs) {
        Arrays.sort(strs, (a, b) -> Integer.compare(b.length(), a.length()));
        int n = strs.length;
        for (int i = 0; i < n; i++) {
            boolean ok = true;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                if (isSubseq(strs[i], strs[j])) {
                    ok = false;
                    break;
                }
            }
            if (ok) return strs[i].length();
        }
        return -1;
    }

    private boolean isSubseq(String s1, String s2) {
        int i = 0;
        for (int j = 0; j < s2.length() && i < s1.length(); j++) {
            if (s1.charAt(i) == s2.charAt(j)) i++;
        }
        return i == s1.length();
    }
}

var findLUSlength = function(strs) {
    const isSubseq = (s1, s2) => {
        let i = 0;
        for (let j = 0; j < s2.length && i < s1.length; j++) {
            if (s1[i] === s2[j]) i++;
        }
        return i === s1.length;
    };
    strs.sort((a, b) => b.length - a.length);
    const n = strs.length;
    for (let i = 0; i < n; i++) {
        let ok = true;
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            if (isSubseq(strs[i], strs[j])) {
                ok = false;
                break;
            }
        }
        if (ok) return strs[i].length;
    }
    return -1;
};
